import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 제출처 미입력 시 기본값 (schema의 submission_to는 NOT NULL)
const DEFAULT_SUBMISSION_TO = '미지정';
// 가정: 발급 부수 미입력 시 기본값 (schema의 copies는 NOT NULL)
const DEFAULT_COPIES = 1;

@Controller('api/v1')
export class FnSfr03205Controller {
  @Post('/certificates')
  @HttpCode(200)
  async createCertificate(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);

    const formRaw = data['certificateFormId'];
    if (formRaw === undefined || formRaw === null || formRaw === '') {
      throw new ApiError(422, 'CERTIFICATE_FORM_REQUIRED', '증명서 종류를 선택해 주세요.');
    }
    const formId = Number(formRaw);
    if (typeof formRaw === 'boolean' || !Number.isInteger(formId) || formId <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '증명서 양식이 올바르지 않습니다.');
    }

    let submissionTo = DEFAULT_SUBMISSION_TO;
    const toRaw = data['submissionTo'];
    if (toRaw !== undefined && toRaw !== null && toRaw !== '') {
      if (typeof toRaw !== 'string' || toRaw.length > 200) {
        throw new ApiError(400, 'VALIDATION_FAILED', '제출처는 200자 이하의 글자여야 합니다.');
      }
      submissionTo = toRaw;
    }

    let copies = DEFAULT_COPIES;
    const copiesRaw = data['copies'];
    if (copiesRaw !== undefined && copiesRaw !== null && copiesRaw !== '') {
      const n = Number(copiesRaw);
      if (typeof copiesRaw === 'boolean' || !Number.isInteger(n) || n <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '발급 부수는 1 이상의 정수여야 합니다.');
      }
      copies = n;
    }

    return transaction(async (db) => {
      const forms = await db.query(
        'SELECT certificate_form_id AS "certificateFormId" FROM certificate_form WHERE certificate_form_id = CAST(:formId AS bigint)',
        { formId },
      );
      if (forms.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '증명서 양식을 찾을 수 없습니다.');
      }

      let rows: any[];
      try {
        // 가정: 채번 규칙 테이블이 스펙에 없어 'CERT-연도-6자리 일련번호'로 부여한다
        rows = await db.query(
          `WITH n AS (SELECT nextval(pg_get_serial_sequence('certificate', 'certificate_id')) AS id)
           INSERT INTO certificate (
             certificate_id, certificate_form_id, employee_id, submission_to, copies,
             status, certificate_no, issued_date, created_at, updated_at
           )
           SELECT n.id, CAST(:formId AS bigint), CAST(:userId AS bigint), :submissionTo, CAST(:copies AS integer),
             '승인', 'CERT-' || to_char(now(), 'YYYY') || '-' || lpad(n.id::text, 6, '0'),
             CAST(now() AS date), now(), now()
           FROM n
           RETURNING certificate_id AS "certificateId", certificate_no AS "certificateNo",
             status AS "status", to_char(issued_date, 'YYYY-MM-DD') AS "issuedDate"`,
          { formId, userId: user.id, submissionTo, copies },
        );
      } catch (e) {
        throw new ApiError(422, 'CERTIFICATE_ISSUE_FAILED', '증명서 발급 처리에 실패했습니다.');
      }
      if (rows.length === 0) {
        throw new ApiError(422, 'CERTIFICATE_ISSUE_FAILED', '증명서 발급 처리에 실패했습니다.');
      }
      return rows[0];
    });
  }
}

