import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  Pager,
  Pairs,
  RefName,
  Select,
  TextInput,
  NumberInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

export default function FnSfr03205Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [formId, setFormId] = useState<number | string>('');
  const [submissionTo, setSubmissionTo] = useState('');
  const [copies, setCopies] = useState<number | string>('');
  const [result, setResult] = useState<Row | undefined>(undefined);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/certificates', role, undefined, { status: applied, page, size: 20 }),
    [applied, page, role],
  );

  const rows = data?.items ?? [];

  const openDrawer = () => {
    setFormId('');
    setSubmissionTo('');
    setCopies('');
    setResult(undefined);
    setOpen(true);
  };

  const submit = async () => {
    if (formId === '' || formId === undefined) {
      throw new Error('증명서 종류를 선택해 주세요.');
    }
    const body: Row = { certificateFormId: formId };
    if (submissionTo !== '') body.submissionTo = submissionTo;
    if (copies !== '') body.copies = copies;
    const created = await call('POST', '/certificates', role, body);
    setResult(created);
    notify('증명서를 발급했습니다.');
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신청 현황</h2>
        <Tiles items={[['신청 건수', <Num value={data?.total ?? 0} />]]} />
      </section>
      <section className="box span-12">
        <h2>증명서 신청 내역</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied(status);
          }}
          onReset={() => {
            setStatus('');
            setApplied('');
            setPage(0);
          }}
        >
          <Field label="상태">
            <Select
              value={status}
              onChange={setStatus}
              options={[['신청', '신청'], ['승인', '승인'], ['반려', '반려']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type="button" onClick={openDrawer}>증명서 신청</button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          columns={[
            { key: 'certificateNo', label: '증명서 번호' },
            {
              key: 'certificateFormId',
              label: '증명서 양식',
              render: (r) => <RefName table="certificate_form" role={role} value={r.certificateFormId} />,
            },
            {
              key: 'employeeId',
              label: '신청자',
              render: (r) => <RefName table="employee" role={role} value={r.employeeId} />,
            },
            { key: 'submissionTo', label: '제출처' },
            { key: 'copies', label: '발급 부수', render: (r) => <Num value={r.copies} /> },
            { key: 'status', label: '상태', render: (r) => <Badge value={r.status} /> },
          ]}
          rows={rows}
          empty="신청 내역이 없습니다."
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {open ? (
        <Drawer title="증명서 신청" onClose={() => setOpen(false)}>
          {result ? (
            <Pairs
              items={[
                ['증명서 번호', String(result.certificateNo ?? '')],
                ['상태', <Badge value={result.status} />],
                ['발급일', <DateText value={result.issuedDate} />],
              ]}
            />
          ) : (
            <Form onSubmit={submit} submit="신청 및 발급">
              <Field label="증명서 양식" required>
                <LookupSelect table="certificate_form" role={role} value={formId} onChange={setFormId} />
              </Field>
              <Field label="제출처">
                <TextInput value={submissionTo} onChange={setSubmissionTo} />
              </Field>
              <Field label="발급 부수">
                <NumberInput value={copies} onChange={setCopies} />
              </Field>
            </Form>
          )}
        </Drawer>
      ) : null}
    </div>
  );
}
